import {ropeShape} from './cloth-config.js';
export const deformableParticleCount=p=>ropeShape(p)?p.particles:p.columns*p.rows;
export function validDeformableMassWeights(p){
 const rows=p.massWeights,count=deformableParticleCount(p);if(!Number.isSafeInteger(count)||count<=0)return false;if(rows===undefined)return true;if(!Array.isArray(rows)||rows.length>count)return false;if(!rows.length)return true;return Object.keys(rows).length===rows.length&&new Set(rows.map(v=>v?.index)).size===rows.length&&rows.every(v=>v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).every(k=>k==='index'||k==='weight')&&Number.isSafeInteger(v.index)&&v.index>=0&&v.index<count&&Number.isFinite(v.weight)&&v.weight>=.001&&v.weight<=1000);
}
export function deformableMasses(p){
 if(!validDeformableMassWeights(p)||!Number.isFinite(p.mass)||p.mass<=0)throw Error('입자 질량 가중치·전체 질량을 확인하세요.');if(!p.massWeights?.length)return null;
 const count=deformableParticleCount(p),masses=new Float32Array(count).fill(1);let total=count;for(const row of p.massWeights){const weight=Math.fround(row.weight);masses[row.index]=weight;total+=weight-1;}const factor=p.mass/total;for(let i=0;i<count;i++)masses[i]*=factor;return masses;
}
export const deformableDistributionContract=Object.freeze({components:['Cloth','Rope2D'],fields:{tensionOnly:'bool default false; structural edges resist stretching and allow slack under compression; bending remains independent',massWeights:'sparse [{index,weight}] relative positive weights .001..1000; unspecified particles weight 1, normalized to existing total mass; [] retains uniform backend path'},editing:'Existing component properties/Undo, componentSetBool/componentSetJson and hb::Components::SetBool/SetText. Changing either rebuilds rest state; material-only hot edits keep the distribution.',ownership:'Dense Float32 masses only while creating a nonuniform body; no extra solver particle pass, worker or whole-particle snapshot. Ordinary component validation/signature still examines authored sparse overrides at sync. Empty weights bypass allocation. Page reads requested actual particle mass.',limits:['Not painted motion-distance tethers or partial pin weights; hard pins remain separate','No approximate hot mass setter: backend requires creation and runtime attachments/pins reset with documented cold rebuild','Tension-only is a structural-edge model, not an inextensible cable, tear/cut or volumetric soft body']});
